import os, re, json, numpy as np

session_file = '/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-3/play/users/u004/system/state/sessions/01a188f9-7fad-7788-8b92-f912a06b76f5.jsonl'
with open(session_file) as f:
    content = f.read()

messages = [json.loads(line) for line in content.strip().split('\n')]

# Extract all grids
all_grids = {}

for msg in messages:
    if msg.get('type') != 'message':
        continue

    text_content = msg['message']['content']
    for item in text_content:
        if item.get('type') == 'text':
            content_str = item['text'].replace('\\n', '\n')

            # Find Demo pair patterns
            demo_pattern = r'Demo pair (\d+) (input|output) \((\d+)x(\d+)\):\n'
            matches = list(re.finditer(demo_pattern, content_str))

            current_label = None
            for m in matches:
                num, side, h, w = int(m.group(1)), m.group(2), int(m.group(3)), int(m.group(4))

                start_idx = m.end()
                rows = []
                idx = start_idx

                while len(rows) < h and idx < len(content_str):
                    line = content_str[idx:idx+1]
                    idx += 1

                    if line.strip():
                        parts = line.strip().split()
                        if len(parts) >= w and all(c.isdigit() for c in parts[:w]):
                            row = [int(p) for p in parts[:w]]
                            rows.append(row)

                key = f"demo_{num}_{side}"
                if rows and all(len(r) == w for r in rows):
                    all_grids[key] = rows

# Also find test input
for msg in messages:
    if msg.get('type') != 'message':
        continue

    text_content = msg['message']['content']
    for item in text_content:
        if item.get('type') == 'text' and 'Test input (14x14)' in item.get('text', ''):
            content_str = item['text'].replace('\\n', '\n')

            idx = content_str.find('Test input (14x14):\n')
            snippet = content_str[idx:idx+500]
            rows = []

            lines = snippet.split('\n')[1:]  # Skip header line

            # Count until we get 14 valid rows
            count = 0
            for line in lines:
                line_stripped = line.strip()
                if line_stripped and all(c.isdigit() or c==' ' for c in line_stripped):
                    parts = line_stripped.split()
                    if len(parts) >= 14:
                        row = [int(p) for p in parts[:14]]
                        rows.append(row)
                        count += 1
                        if count == 14:
                            break

            all_grids['test_input'] = rows

print(f"Loaded {len(all_grids)} grids")
for k, v in all_grids.items():
    print(f"{k}: {len(v)}x{v[0][0]}")
